UPDATE USER_TOTP_STATE SET SECRET = #{secret,jdbcType=VARCHAR},
    ENROLLED_AT = #{enrolledAt,jdbcType=TIMESTAMP}, LAST_USED_STEP = #{lastUsedStep},
    GENERATION = #{generation}, TOKEN_HASH = #{tokenHash,jdbcType=VARCHAR},
    CHALLENGE_DATA = #{challengeData,jdbcType=VARCHAR}, EXPIRES_AT = #{expiresAt},
    ATTEMPTS = #{attempts}, ATTEMPT_WINDOW = #{attemptWindow}
WHERE USER_ID = #{userId}
